import re, sys
html_text = sys.stdin.read()
# Look for 'HTML' 'CSS' 'JavaScript' as text nodes in specific contexts
for match in re.finditer(r'<span[^>]*class=\"[^\"]*repo-language-color[^\"]*\"[^>]*>\s*</span>\s*<span[^>]*>([^<]+)', html_text):
    print('repo-language-color:', match.group(1))
for match in re.finditer(r'<a[^>]*href=\"/canada-ca/a11y/search\?l=[^\"]*\"[^>]*>([^<]+)', html_text):
    print('language search:', match.group(1))
for match in re.finditer(r'<span[^>]*class=\"[^\"]*d-inline-block[^\"]*\"[^>]*>([^<]+)', html_text):
    if match.group(1).strip() in ['HTML', 'CSS', 'JavaScript', 'Python', 'Ruby', 'Shell']:
        print('d-inline-block:', match.group(1).strip())
"

